PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?org ?orgLabel ?repCity ?repState ?numProc ?naicsCode ?naicsText
WHERE {
  {
    SELECT ?org ?orgLabel
           (MIN(IF(LCASE(STR(?cityLabel)) = "austin", 0, 1)) AS ?austinRank)
           (SAMPLE(?cityLabel) AS ?repCity)
           (SAMPLE(?stateLabel) AS ?repState)
           (SAMPLE(?naicsCodeVal) AS ?naicsCode)
           (SAMPLE(?naicsTextVal) AS ?naicsText)
           (COUNT(DISTINCT LCASE(STR(?procLabel))) AS ?numProc)
    WHERE {
      ?org a iof-core:Manufacturer ;
           rdfs:label ?orgLabel ;
           sdk:hasNumberOfEmployees ?empStr ;
           sdk:organizationLocatedIn ?site .
      BIND(xsd:integer(?empStr) AS ?emp)
      FILTER(?emp >= 10 && ?emp <= 500)

      ?site sdk:hasZIPcode ?zip .
      ?zip a sdk:USPostalCode .
      ?site sdk:locatedInCity ?city .
      ?city rdfs:label ?cityLabel ;
            sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      FILTER(REGEX(STR(?stateLabel), "^(Texas|Indiana|Indian)$", "i"))

      OPTIONAL {
        ?org sdk:hasPrimaryNAICSClassifier ?naics .
        OPTIONAL { ?naics sdk:hasNAICSCodeValue ?naicsCodeVal . }
        OPTIONAL { ?naics sdk:hasNAICSTextValue ?naicsTextVal . }
      }

      ?org sdk:hasProcessCapability ?proc .
      ?proc rdfs:label ?procLabel .

      FILTER EXISTS {
        ?org sdk:hasProcessCapability ?cap1 .
        ?cap1 rdfs:label ?cap1Label .
        FILTER(REGEX(LCASE(STR(?cap1Label)), "cnc") && REGEX(LCASE(STR(?cap1Label)), "mill"))
      }
      FILTER EXISTS {
        ?org sdk:hasProcessCapability ?cap2 .
        ?cap2 rdfs:label ?cap2Label .
        FILTER(REGEX(LCASE(STR(?cap2Label)), "anodiz"))
      }

      FILTER EXISTS {
        ?org sdk:hasMaterialCapability ?matCap .
        ?matCap rdfs:label ?matLabel .
        FILTER(REGEX(LCASE(STR(?matLabel)), "alumin(i)?um") || REGEX(LCASE(STR(?matLabel)), "titanium"))
      }

      FILTER EXISTS {
        ?org sdk:suppliesToIndustry ?ind .
        ?ind rdfs:label ?indLabel .
        FILTER(REGEX(LCASE(STR(?indLabel)), "aerospace"))
      }
    }
    GROUP BY ?org ?orgLabel
  }
}
ORDER BY DESC(?numProc) ASC(?austinRank) ?orgLabel
LIMIT 10

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry .
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
ORDER BY ?industryLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?org ?orgLabel ?stateLabel
WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasProcessCapability ?cap ;
       sdk:organizationLocatedIn ?site .
  ?cap a sdk:MachiningCapability .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  OPTIONAL { ?org rdfs:label ?orgLabel . }
  FILTER(LCASE(STR(?stateLabel)) IN (
    "illinois","indiana","iowa","kansas","michigan","minnesota","missouri",
    "nebraska","north dakota","ohio","south dakota","wisconsin"
  ))
}

SELECT ?s ?p ?o
WHERE {
  ?s ?p ?o .
}
LIMIT 10

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?org ?orgLabel ?repCity ?repState ?processCount ?naicsCode ?naicsText
WHERE {
  {
    SELECT ?org ?orgLabel
           (SAMPLE(?cityLabel) AS ?repCity)
           (SAMPLE(?stateLabel) AS ?repState)
           (SAMPLE(xsd:double(?latStr)) AS ?lat)
           (SAMPLE(xsd:double(?lonStr)) AS ?lon)
           (COUNT(DISTINCT ?capAll) AS ?processCount)
           (SAMPLE(?naicsCodeVal) AS ?naicsCode)
           (SAMPLE(?naicsTextVal) AS ?naicsText)
    WHERE {
      ?org a iof-core:Manufacturer ;
           rdfs:label ?orgLabel ;
           sdk:organizationLocatedIn ?site ;
           sdk:hasNumberOfEmployees ?empStr .
      BIND(xsd:integer(?empStr) AS ?emp)
      FILTER(?emp >= 10 && ?emp <= 5000)

      ?site sdk:locatedInCity ?city .
      ?city rdfs:label ?cityLabel ;
            sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      VALUES ?midwestState {
        "Illinois" "Indiana" "Iowa" "Kansas" "Michigan" "Minnesota"
        "Missouri" "Nebraska" "North Dakota" "Ohio" "South Dakota" "Wisconsin"
      }
      FILTER(LCASE(STR(?stateLabel)) = LCASE(?midwestState))

      OPTIONAL {
        ?site sdk:hasSpatialCoordinates ?coord .
        OPTIONAL { ?coord sdk:hasLatitudeValue ?latStr . }
        OPTIONAL { ?coord sdk:hasLongitudeValue ?lonStr . }
      }

      OPTIONAL {
        ?org sdk:hasPrimaryNAICSClassifier ?naicsInst .
        OPTIONAL { ?naicsInst sdk:hasNAICSCodeValue ?naicsCodeVal . }
        OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsTextVal . }
      }

      ?org sdk:hasProcessCapability ?capAll .

      FILTER EXISTS {
        ?org sdk:hasProcessCapability ?capAnod .
        ?capAnod rdfs:label ?capAnodLabel .
        FILTER(CONTAINS(LCASE(STR(?capAnodLabel)), "anodiz"))
      }

      FILTER EXISTS {
        ?org sdk:hasMaterialCapability ?matCap .
        ?matCap rdfs:label ?matLabel .
        FILTER(CONTAINS(LCASE(STR(?matLabel)), "aluminum") || CONTAINS(LCASE(STR(?matLabel)), "titanium"))
      }

      FILTER EXISTS {
        ?org sdk:hasProcessCapability ?capPP .
        ?capPP rdfs:label ?capPPLabel .
        FILTER(CONTAINS(LCASE(STR(?capPPLabel)), "passivation") || CONTAINS(LCASE(STR(?capPPLabel)), "powder coat"))
      }

      FILTER EXISTS {
        ?org sdk:suppliesToIndustry ?indAero .
        ?indAero rdfs:label ?indAeroLabel .
        FILTER(CONTAINS(LCASE(STR(?indAeroLabel)), "aerospace"))
      }

      FILTER EXISTS {
        ?org sdk:suppliesToIndustry ?indMil .
        ?indMil rdfs:label ?indMilLabel .
        FILTER(CONTAINS(LCASE(STR(?indMilLabel)), "militar"))
      }
    }
    GROUP BY ?org ?orgLabel
  }
  BIND(30.2672 AS ?austinLat)
  BIND(-97.7431 AS ?austinLon)
  BIND((?lat - ?austinLat) AS ?dLat)
  BIND((?lon - ?austinLon) AS ?dLon)
  BIND((?dLat*?dLat + ?dLon*?dLon) AS ?distance)
}
ORDER BY DESC(?processCount) ASC(?distance) ASC(?orgLabel)
LIMIT 10

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?companyLabel ?cityLabel ?stateLabel ?naicsCodeValue ?naicsTextValue (COUNT(DISTINCT ?processCap) AS ?processCount) ?website
WHERE {
  ?company a iof-core:Manufacturer ;
          rdfs:label ?companyLabel ;
          sdk:hasPrimaryNAICSClassifier ?naicsInst ;
          sdk:organizationLocatedIn ?site ;
          sdk:hasProcessCapability ?processCap ;
          sdk:hasWebAddress ?website .
  ?naicsInst sdk:hasNAICSCodeValue ?naicsCodeValue ;
             sdk:hasNAICSTextValue ?naicsTextValue .
  ?site sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .

  # Manufacturer must be headquartered in the midwest
  ?site sdk:locatedInRegion sdk:region-midwest .

  # Must perform anodizing on aluminum or titanium
  ?company sdk:hasProcessCapability ?anodizingCap .
  ?anodizingCap a sdk:AnodizingCapability .
  ?anodizingCap sdk:onMaterial ?mat .
  VALUES ?mat { sdk:material-aluminum sdk:material-titanium }

  # Must offer passivation or powder coating (OR)
  {
    ?company sdk:hasProcessCapability ?passivationCap .
    ?passivationCap a sdk:PassivationCapability .
  }
  UNION
  {
    ?company sdk:hasProcessCapability ?powderCoatingCap .
    ?powderCoatingCap a sdk:PowderCoatingCapability .
  }

  # Not woman-owned
  FILTER NOT EXISTS {
    ?company sdk:hasSpecialBusinessStatus sdk:status-woman-owned .
  }

  # Supplies to both the aerospace and military industries
  ?company sdk:suppliesToIndustry sdk:industry-aerospace .
  ?company sdk:suppliesToIndustry sdk:industry-military .

  # At least one US site
  ?site sdk:locatedInCountry sdk:country-US .
}
GROUP BY ?company ?companyLabel ?cityLabel ?stateLabel ?naicsCodeValue ?naicsTextValue ?website
HAVING (COUNT(DISTINCT ?processCap) > 0)
ORDER BY DESC(?processCount) ASC(?distanceToAustin)
LIMIT 10

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?org ?orgLabel
       (SAMPLE(?cityLabel) AS ?repCity)
       (SAMPLE(?stateLabel) AS ?repState)
       (COUNT(DISTINCT ?procCap) AS ?processCount)
       (SAMPLE(?naicsCode) AS ?naicsCode)
       (SAMPLE(?naicsText) AS ?naicsText)
       (MIN(?siteDist2) AS ?dist2)
WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?orgLabel ;
       sdk:organizationLocatedIn ?hqSite .

  ?hqSite sdk:locatedInCity ?hqCity .
  ?hqCity rdfs:label ?cityLabel ;
          sdk:locatedInState ?hqState .
  ?hqState rdfs:label ?stateLabel .
  FILTER(LCASE(?stateLabel) IN ("illinois","indiana","iowa","kansas","michigan","minnesota","missouri","nebraska","north dakota","ohio","south dakota","wisconsin"))

  FILTER EXISTS {
    ?org sdk:suppliesToIndustry ?indA .
    ?indA rdfs:label ?indALabel .
    FILTER(CONTAINS(LCASE(?indALabel), "aerospace"))
  }
  FILTER EXISTS {
    ?org sdk:suppliesToIndustry ?indM .
    ?indM rdfs:label ?indMLabel .
    FILTER(CONTAINS(LCASE(?indMLabel), "military"))
  }

  FILTER EXISTS {
    ?org sdk:hasProcessCapability ?anodProc .
    ?anodProc rdfs:label ?anodLabel .
    FILTER(CONTAINS(LCASE(?anodLabel), "anodiz"))
  }

  FILTER EXISTS {
    ?org sdk:hasMaterialCapability ?matCapReq .
    ?matCapReq rdfs:label ?matLabel .
    FILTER(LCASE(?matLabel) IN ("aluminum","titanium"))
  }

  FILTER EXISTS {
    ?org sdk:hasProcessCapability ?otherProc .
    ?otherProc rdfs:label ?otherLabel .
    FILTER(CONTAINS(LCASE(?otherLabel), "passivation") || CONTAINS(LCASE(?otherLabel), "powder coat"))
  }

  ?org sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip a sdk:USPostalCode .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?latStr ;
          sdk:hasLongitudeValue ?lonStr .
  BIND(xsd:decimal(?latStr) AS ?lat)
  BIND(xsd:decimal(?lonStr) AS ?lon)
  BIND(30.2672 AS ?austinLat)
  BIND(-97.7431 AS ?austinLon)
  BIND((?lat-?austinLat) * (?lat-?austinLat) + (?lon-?austinLon) * (?lon-?austinLon) AS ?siteDist2)

  OPTIONAL { ?org sdk:hasProcessCapability ?procCap . }

  OPTIONAL {
    ?org sdk:hasPrimaryNAICSClassifier ?naicsInst .
    OPTIONAL { ?naicsInst sdk:hasNAICSTextValue ?naicsText . }
    OPTIONAL { ?naicsInst sdk:hasNAICSCodeValue ?naicsCode . }
  }
}
GROUP BY ?org ?orgLabel
ORDER BY DESC(?processCount) ASC(?dist2)
LIMIT 10

