PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?cityLabel ?stateLabel ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
    rdfs:label ?manufacturerLabel ;
    sdk:organizationLocatedIn ?site ;
    sdk:suppliesToIndustry ?industry .
  ?site sdk:hasSpatialCoordinates ?coordinates ;
        sdk:locatedInCity ?city .
  ?coordinates sdk:hasLatitudeValue ?latitude ;
               sdk:hasLongitudeValue ?longitude .
  ?city sdk:locatedInState ?state ;
        rdfs:label ?cityLabel .
  ?state rdfs:label ?stateLabel .
  FILTER regex(?stateLabel, "Illinois|Indiana|Iowa|Kansas|Michigan|Minnesota|Missouri|Nebraska|North Dakota|Ohio|South Dakota|Wisconsin", "i")
  FILTER regex(?industry, "Aerospace", "i")
  BIND(( ( (?latitude-33.424239)*(?latitude-33.424239) + (?longitude-111.928052)*(?longitude-111.928052) ) ) AS ?distanceToASU)
}
ORDER BY ?distanceToASU

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?cityLabel ?stateLabel ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site ;
                sdk:hasCertificate ?cert ;
                sdk:suppliesToIndustry ?industry .
  ?cert a sdk:ISO9001 .
  ?site sdk:locatedInCity ?city ;
        sdk:hasSpatialCoordinates ?coords .
  ?city sdk:locatedInState ?state ;
        rdfs:label ?cityLabel .
  ?state rdfs:label ?stateLabel .
  ?coords sdk:hasLatitudeValue ?latitude ;
          sdk:hasLongitudeValue ?longitude .

  # Midwest filtering by state names:
  FILTER(?stateLabel IN ("Illinois", "Indiana", "Iowa", "Kansas", "Michigan", "Minnesota", "Missouri", "Nebraska", "North Dakota", "Ohio", "South Dakota", "Wisconsin"))

  # Aerospace or Agriculture industry
  ?industry rdfs:label ?industryLabel .
  FILTER(CONTAINS(LCASE(?industryLabel), "aerospace") || CONTAINS(LCASE(?industryLabel), "agriculture"))
}
ORDER BY (ABS(xsd:double(?latitude) - 33.4222) + ABS(xsd:double(?longitude) + 111.9389))

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?cityLabel ?stateLabel ?lat ?lon ?distance2
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:organizationLocatedIn ?site ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasCertificate ?cert .
  VALUES ?certType { sdk:ISO9001 sdk:AS9100Certificate }
  ?cert a ?certType .

  ?site sdk:hasSpatialCoordinates ?coords ;
        sdk:locatedInCity ?city .
  ?city rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .

  ?coords sdk:hasLatitudeValue ?latLit ;
          sdk:hasLongitudeValue ?lonLit .
  BIND(xsd:double(?latLit) AS ?lat)
  BIND(xsd:double(?lonLit) AS ?lon)

  ?industry rdfs:label ?industryLabel .
  FILTER(CONTAINS(LCASE(STR(?industryLabel)), "aerospace") || CONTAINS(LCASE(STR(?industryLabel)), "agric"))

  FILTER(LCASE(STR(?stateLabel)) IN (
    "illinois","indiana","iowa","kansas","michigan","minnesota","missouri","nebraska","north dakota","ohio","south dakota","wisconsin"
  ))

  BIND(33.424239 AS ?asuLat)
  BIND(-111.928053 AS ?asuLon)
  BIND((?lat - ?asuLat) * (?lat - ?asuLat) + (?lon - ?asuLon) * (?lon - ?asuLon) AS ?distance2)
}
ORDER BY ASC(?distance2)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?m ?name ?stateLabel ?distance
WHERE {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:organizationLocatedIn ?site ;
     sdk:hasCertificate ?cert ;
     sdk:suppliesToIndustry ?industry .

  ?cert a ?certType .
  VALUES ?certType {
    sdk:ISO9001
    sdk:AS9100Certificate
    sdk:AS9120
    sdk:AS9003
    sdk:AS9000
    sdk:QSQuality
    sdk:QualityCertificate
    sdk:AerospaceQualityCertificate
  }

  ?site sdk:hasSpatialCoordinates ?coords ;
        sdk:locatedInCity ?city .
  ?coords sdk:hasLatitudeValue ?latStr ;
          sdk:hasLongitudeValue ?lonStr .
  BIND(xsd:double(?latStr) AS ?lat)
  BIND(xsd:double(?lonStr) AS ?lon)

  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  FILTER(?stateLabel IN ("Illinois","Indiana","Iowa","Kansas","Michigan","Minnesota","Missouri","Nebraska","North Dakota","Ohio","South Dakota","Wisconsin"))

  OPTIONAL { ?industry rdfs:label ?industryLabel . }
  OPTIONAL { ?industry a ?industryType . }
  FILTER(
    (BOUND(?industryLabel) && REGEX(LCASE(?industryLabel), "aerospace|agric")) ||
    (BOUND(?industryType) && REGEX(STR(?industryType), "Aerospace|Agric", "i"))
  )

  BIND(xsd:double("33.4242") AS ?asuLat)
  BIND(xsd:double("-111.9281") AS ?asuLon)
  BIND( ((?lat - ?asuLat) * (?lat - ?asuLat) + (?lon - ?asuLon) * (?lon - ?asuLon)) AS ?distance )
}
ORDER BY ASC(?distance)

