PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?stateLabel ?manufacturer ?manufacturerLabel ?numEmployees ?rank WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasNumberOfEmployees ?numStr ;
                sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  BIND(xsd:integer(REPLACE(?numStr, ",", "")) AS ?numEmployees)

  {
    SELECT ?manufacturer (COUNT(?other) AS ?higher) WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:hasNumberOfEmployees ?numStr ;
                    sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .

      ?other a iof-core:Manufacturer ;
             sdk:hasNumberOfEmployees ?otherNumStr ;
             sdk:organizationLocatedIn ?otherSite .
      ?otherSite sdk:locatedInCity ?otherCity .
      ?otherCity sdk:locatedInState ?state .

      BIND(xsd:integer(REPLACE(?otherNumStr, ",", "")) AS ?otherNum)
      BIND(xsd:integer(REPLACE(?numStr, ",", "")) AS ?thisNum)
      FILTER( ?otherNum > ?thisNum || (?otherNum = ?thisNum && str(?other) < str(?manufacturer)) )
    } GROUP BY ?manufacturer
  }
  BIND((?higher + 1) AS ?rank)
  FILTER(?rank <= 3)
}
ORDER BY ?stateLabel DESC(?numEmployees)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manufacturer ?manufacturerLabel ?employees ?avgEmployees
WHERE {
  {
    SELECT ?industry (AVG(?empVal) AS ?avgEmployees)
    WHERE {
      ?m2 a iof-core:Manufacturer ;
          sdk:suppliesToIndustry ?industry ;
          sdk:hasNumberOfEmployees ?emp2 .
      BIND(xsd:decimal(REPLACE(?emp2, ",", "")) AS ?empVal)
    }
    GROUP BY ?industry
  }
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasNumberOfEmployees ?employees .
  BIND(xsd:decimal(REPLACE(?employees, ",", "")) AS ?empValMain)
  FILTER(?empValMain > ?avgEmployees)
  OPTIONAL { ?industry rdfs:label ?industryLabel }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}
ORDER BY ?industryLabel ?manufacturerLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?requestedName (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  VALUES ?requestedName { "Machining" "Coating" "Heat Treating" }
  OPTIONAL {
    ?m a iof-core:Manufacturer ;
       sdk:hasProcessCapability ?cap .
    ?cap a ?capClass .
    OPTIONAL { ?cap rdfs:label ?capLabel }
    OPTIONAL { ?capClass rdfs:label ?classLabel }
    FILTER(
      (BOUND(?capLabel) && CONTAINS(LCASE(STR(?capLabel)), LCASE(?requestedName)))
      ||
      (BOUND(?classLabel) && CONTAINS(LCASE(STR(?classLabel)), LCASE(?requestedName)))
    )
  }
}
GROUP BY ?requestedName
ORDER BY ?requestedName

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>

SELECT ?stateLabel (AVG(?empNum) AS ?averageEmployees)
WHERE {
  {
    SELECT DISTINCT ?org ?stateLabel ?empNum WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:manufactures ?prod ;
           sdk:hasNumberOfEmployees ?empStr ;
           sdk:organizationLocatedIn ?site .
      ?prod rdfs:label ?prodLabel .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      FILTER(CONTAINS(LCASE(str(?prodLabel)), "pipe"))
      BIND(REPLACE(str(?empStr), ",", "") AS ?empNoComma)
      BIND(xsd:decimal(?empNoComma) AS ?empNum)
    }
  }
}
GROUP BY ?stateLabel
ORDER BY ?averageEmployees

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?manufacturer ?label ?numCertificates WHERE {
  {
    SELECT ?manufacturer (COUNT(DISTINCT ?cert) AS ?numCertificates) WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
    } GROUP BY ?manufacturer
  }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  {
    SELECT (AVG(?c) AS ?avg) WHERE {
      {
        SELECT ?m (COUNT(DISTINCT ?cert2) AS ?c) WHERE {
          ?m a iof-core:Manufacturer .
          OPTIONAL { ?m sdk:hasCertificate ?cert2 . }
        } GROUP BY ?m
      }
    }
  }
  FILTER(xsd:decimal(?numCertificates) > ?avg)
}
ORDER BY DESC(?numCertificates)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?naics ?naicsLabel ?state ?stateLabel ?count WHERE {
  {
    SELECT ?naics ?state ?count (COUNT(?s2) AS ?better) WHERE {
      {
        SELECT ?naics ?state (COUNT(DISTINCT ?org) AS ?count) WHERE {
          ?org a iof-core:Manufacturer ;
               sdk:hasPrimaryNAICSClassifier ?naics ;
               sdk:organizationLocatedIn ?site .
          ?site sdk:locatedInCity ?city .
          ?city sdk:locatedInState ?state .
        } GROUP BY ?naics ?state
      }
      {
        SELECT ?naics ?s2 (COUNT(DISTINCT ?org2) AS ?count2) WHERE {
          ?org2 a iof-core:Manufacturer ;
                sdk:hasPrimaryNAICSClassifier ?naics ;
                sdk:organizationLocatedIn ?site2 .
          ?site2 sdk:locatedInCity ?city2 .
          ?city2 sdk:locatedInState ?s2 .
        } GROUP BY ?naics ?s2
      }
      FILTER( ?count2 > ?count || ( ?count2 = ?count && str(?s2) < str(?state) ) )
    } GROUP BY ?naics ?state ?count
  }
  FILTER( ?better < 5 )
  OPTIONAL { ?naics rdfs:label ?naicsLabel . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }
}
ORDER BY ?naicsLabel DESC(?count)

