       sdk:suppliesToIndustry ?ind1 , ?ind2 .
  ?ind1 a sdk:RenewableEnergyIndustry .
  ?ind2 a sdk:UtilitiesIndustry .
  FILTER(?ind1 != ?ind2)
  FILTER NOT EXISTS {
    ?org sdk:suppliesToIndustry ?other .
    FILTER(?other != ?ind1 && ?other != ?ind2)
  }
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?company ?companyLabel ?productCount WHERE {
  {
    SELECT ?company (COUNT(DISTINCT ?product) AS ?productCount) WHERE {
      ?company a iof-core:Manufacturer .
      ?company sdk:manufactures ?product .
    } GROUP BY ?company
  }
  {
    SELECT (MAX(?c) AS ?maxCount) WHERE {
      {
        SELECT ?comp (COUNT(DISTINCT ?prod) AS ?c) WHERE {
          ?comp a iof-core:Manufacturer .
          ?comp sdk:manufactures ?prod .
        } GROUP BY ?comp
      }
    }
  }
  FILTER(?productCount = ?maxCount)
  OPTIONAL { ?company rdfs:label ?companyLabel }
}
ORDER BY ?companyLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel ?num WHERE {
  {
    SELECT ?industry (COUNT(DISTINCT ?manu) AS ?num) WHERE {
      ?manu a iof-core:Manufacturer ;
            sdk:suppliesToIndustry ?industry .
    }
    GROUP BY ?industry
  }
  OPTIONAL { ?industry rdfs:label ?industryLabel. }
  {
    SELECT (MAX(?c) AS ?max) WHERE {
      {
        SELECT (COUNT(DISTINCT ?m) AS ?c) WHERE {
          ?m a iof-core:Manufacturer ;
             sdk:suppliesToIndustry ?ind .
        }
        GROUP BY ?ind
      }
    }
  }
  FILTER(?num = ?max)
}
ORDER BY DESC(?num)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel ?org ?orgLabel ?headcountNum WHERE {
  {
    SELECT ?state (MAX(?hcNum) AS ?maxHeadcount) WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasNumberOfEmployees ?hcStr ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      BIND(xsd:integer(REPLACE(STR(?hcStr), "[^0-9]", "")) AS ?hcNum)
    } GROUP BY ?state
  }
  ?org a iof-core:Manufacturer ;
       sdk:hasNumberOfEmployees ?hcStr ;
       sdk:organizationLocatedIn ?site ;
       rdfs:label ?orgLabel .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
  BIND(xsd:integer(REPLACE(STR(?hcStr), "[^0-9]", "")) AS ?headcountNum)
  FILTER(?headcountNum = ?maxHeadcount)
}
ORDER BY ?stateLabel ?orgLabel

