PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?label ?zipVal WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:hasZIPcode ?zip .
  ?zip sdk:hasIntegerValue ?zipVal .

  FILTER (
    NOT EXISTS { ?site sdk:locatedInCity ?city }
    ||
    (
      EXISTS { ?site sdk:locatedInCity ?city }
      && NOT EXISTS { ?city sdk:locatedInState ?state }
    )
  )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?certCount WHERE {
  {
    SELECT (AVG(?c) AS ?avgCert) WHERE {
      SELECT ?m (COUNT(?cert) AS ?c) WHERE {
        ?m a iof-core:Manufacturer .
        OPTIONAL { ?m sdk:hasCertificate ?cert . }
      } GROUP BY ?m
    }
  }
  {
    SELECT ?manufacturer (COUNT(?cert) AS ?certCount) WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
    } GROUP BY ?manufacturer
  }
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  FILTER(?certCount > ?avgCert)
}
ORDER BY DESC(?certCount)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?industry ?industryLabel ?manu ?manuLabel ?employees ?avgEmployees WHERE {
  ?manu a iof-core:Manufacturer ;
        sdk:suppliesToIndustry ?industry ;
        sdk:hasNumberOfEmployees ?empStr .
  BIND(xsd:integer(REPLACE(str(?empStr), ",", "")) AS ?employees)

  {
    SELECT ?industry (AVG(?empVal) AS ?avgEmployees) WHERE {
      ?m2 a iof-core:Manufacturer ;
          sdk:suppliesToIndustry ?industry ;
          sdk:hasNumberOfEmployees ?empStr2 .
      BIND(xsd:decimal(REPLACE(str(?empStr2), ",", "")) AS ?empVal)
    } GROUP BY ?industry
  }

  FILTER(?employees > ?avgEmployees)

  OPTIONAL { ?manu rdfs:label ?manuLabel }
  OPTIONAL { ?industry rdfs:label ?industryLabel }
}
ORDER BY ?industryLabel ?manuLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?stateLabel (AVG(?empNum) AS ?avgEmployees)
WHERE {
  {
    SELECT DISTINCT ?man ?state ?stateLabel ?empNum WHERE {
      ?man a iof-core:Manufacturer ;
           sdk:manufactures ?prod ;
           sdk:hasNumberOfEmployees ?empStr ;
           sdk:organizationLocatedIn ?site .
      ?prod rdfs:label ?prodLabel .
      FILTER(regex(str(?prodLabel), "[0-9]")) .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabel .
      BIND(xsd:decimal(REPLACE(str(?empStr), ",", "")) AS ?empNum)
    }
  }
}
GROUP BY ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stateLabel ?procCount ?matCount
WHERE {
  {
    SELECT ?state ?stateLabel (COUNT(DISTINCT ?procCap) AS ?procCount) (COUNT(DISTINCT ?matCap) AS ?matCount)
    WHERE {
      ?man a iof-core:Manufacturer ;
           sdk:organizationLocatedIn ?site .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel . }
      OPTIONAL { ?man sdk:hasProcessCapability ?procCap . }
      OPTIONAL { ?man sdk:hasMaterialCapability ?matCap . }
    }
    GROUP BY ?state ?stateLabel
  }
}
ORDER BY DESC(?procCount) DESC(?matCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsCode ?naicsText ?numManufacturers ?numProducts ?avgEmployees
WHERE {
  {
    SELECT ?naics ?naicsCode ?naicsText (COUNT(DISTINCT ?manu) AS ?numManufacturers) (AVG(?empVal) AS ?avgEmployees)
    WHERE {
      ?manu a iof-core:Manufacturer ;
            sdk:hasPrimaryNAICSClassifier ?naics .
      ?naics sdk:hasNAICSCodeValue ?naicsCode ;
             sdk:hasNAICSTextValue ?naicsText .
      OPTIONAL {
        ?manu sdk:hasNumberOfEmployees ?empStr .
        BIND(xsd:decimal(REPLACE(STR(?empStr), ",", "")) AS ?empVal)
      }
    }
    GROUP BY ?naics ?naicsCode ?naicsText
  }
  OPTIONAL {
    SELECT ?naics (COUNT(DISTINCT ?product) AS ?numProducts)
    WHERE {
      ?manu2 a iof-core:Manufacturer ;
             sdk:hasPrimaryNAICSClassifier ?naics ;
             sdk:manufactures ?product .
    }
    GROUP BY ?naics
  }
}
ORDER BY ?naicsCode

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
