PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label ?zipVal ?lat WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site ;
                rdfs:label ?label .
  ?site sdk:hasZIPcode ?zip ;
        sdk:hasSpatialCoordinates ?coord .
  ?zip sdk:hasIntegerValue ?zipVal .
  ?coord sdk:hasLatitudeValue ?lat .
  FILTER( REPLACE(STR(?zipVal), "\\.0$", "") != "00000" )
  FILTER( xsd:decimal(?lat) > xsd:decimal(?1) )
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:manufactures ?product ;
                sdk:hasProcessCapability ?proc ;
                sdk:hasMaterialCapability ?mat .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel }
}
GROUP BY ?manufacturer ?manufacturerLabel
HAVING (
  COUNT(DISTINCT ?product) = 2 &&
  COUNT(DISTINCT ?proc) = 2 &&
  COUNT(DISTINCT ?mat) = 2
)

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT DISTINCT ?cap ?label WHERE {
  ?org a iof-core:Manufacturer ;
       sdk:hasMaterialCapability ?cap .
  ?cap rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?label)), "steel"))
}
LIMIT 100

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?product) AS ?productCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label .
  OPTIONAL { ?manufacturer sdk:manufactures ?product . }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?productCount)
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?label (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label . }
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
  }
}
GROUP BY ?manufacturer ?label
ORDER BY DESC(?totalCapabilities)
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capName; SEPARATOR=", ") AS ?capabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
    ?cap rdfs:label ?capName .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?latitude ?longitude
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coords .
      OPTIONAL { ?coords sdk:hasLatitudeValue ?latitude. }
      OPTIONAL { ?coords sdk:hasLongitudeValue ?longitude. }
    }
  }
}
ORDER BY ?manufacturerLabel
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?city ?cityLabel (COUNT(DISTINCT ?manufacturer) AS ?manufacturerCount)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  OPTIONAL { ?city rdfs:label ?cityLabel . }
}
GROUP BY ?city ?cityLabel
ORDER BY DESC(?manufacturerCount)
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
SELECT DISTINCT ?manufacturer ?manufacturerLabel ?siteCoordinates WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:hasSpatialCoordinates ?coords .
      OPTIONAL {
        ?coords sdk:hasLatitudeValue ?lat .
        ?coords sdk:hasLongitudeValue ?long .
      }
    }
  }
  BIND(
    IF(
      (BOUND(?lat) && BOUND(?long)),
      CONCAT(STR(?lat), ",", STR(?long)),
      "no-coords"
    ) AS ?siteCoordinates
  )
}
ORDER BY ?manufacturerLabel
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manLabel WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manLabel .
  {
    ?manufacturer sdk:hasProcessCapability ?proc .
    ?proc rdfs:label ?procLabel .
    FILTER(regex(str(?procLabel), "ing$", "i"))
  }
  UNION
  {
    ?manufacturer sdk:hasMaterialCapability ?mat .
  }
}
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?companyLabel ?site ?city ?state ?stateName WHERE {
  ?company a iof-core:Manufacturer ;
           sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateName .
  OPTIONAL { ?company rdfs:label ?companyLabel . }
}
ORDER BY ?company
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?manufacturer (COALESCE(?descText, ?name) AS ?displayName)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?name . }
  OPTIONAL {
    ?manufacturer iof-core:describedBy ?descNode .
    ?descNode iof-scro:hasTextValue ?descText .
  }
}
ORDER BY (COALESCE(?descText, ?name))
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?capLabel; SEPARATOR=", ") AS ?capabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel .
  OPTIONAL {
    ?manufacturer (sdk:hasProcessCapability|sdk:hasMaterialCapability) ?cap .
    ?cap rdfs:label ?capLabel .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?company ?name WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name .
  FILTER( LANG(?name) = "" || LANGMATCHES(LANG(?name), "en") )
} ORDER BY ?company
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?naicsText WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:hasPrimaryNAICSClassifier ?naics .
    ?naics sdk:hasNAICSTextValue ?naicsText .
  }
}
ORDER BY ?manufacturer
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?cityLabel ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    OPTIONAL {
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
      OPTIONAL {
        ?city sdk:locatedInState ?stateViaCity .
        OPTIONAL { ?stateViaCity rdfs:label ?stateLabelFromCity . }
      }
    }
    OPTIONAL {
      ?site sdk:locatedInState ?stateViaSite .
      OPTIONAL { ?stateViaSite rdfs:label ?stateLabelFromSite . }
    }
  }
  BIND(COALESCE(?stateLabelFromCity, ?stateLabelFromSite) AS ?stateLabel)
}
ORDER BY ?manufacturerLabel ?cityLabel ?stateLabel
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel (GROUP_CONCAT(DISTINCT ?itemLabel; SEPARATOR=", ") AS ?items)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel .
  OPTIONAL {
    ?manufacturer (sdk:manufactures|sdk:hasCertificate) ?item .
    ?item rdfs:label ?itemLabel .
  }
}
GROUP BY ?manufacturer ?manufacturerLabel
ORDER BY ?manufacturerLabel
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?capability ?capLabel ?capabilityType WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel. }
  OPTIONAL {
    {
      ?manufacturer sdk:hasProcessCapability ?capability .
      ?capability rdfs:label ?capLabel .
      BIND("process" AS ?capabilityType)
    } UNION {
      ?manufacturer sdk:hasMaterialCapability ?capability .
      ?capability rdfs:label ?capLabel .
      BIND("material" AS ?capabilityType)
    }
  }
}
ORDER BY ?manufacturer ?capability
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?cityState WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL {
    ?manufacturer sdk:organizationLocatedIn ?site .
    ?site sdk:locatedInCity ?city .
    ?city rdfs:label ?cityLabelRaw .
    OPTIONAL {
      ?city sdk:locatedInState ?state .
      ?state rdfs:label ?stateLabelRaw .
    }
  }
  BIND(COALESCE(?cityLabelRaw, "Unknown") AS ?cityLabel)
  BIND(COALESCE(?stateLabelRaw, "Unknown") AS ?stateLabel)
  BIND(CONCAT(?cityLabel, ", ", ?stateLabel) AS ?cityState)
}
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }

  ?manufacturer (sdk:organizationLocatedIn/sdk:locatedInCity/sdk:locatedInState | sdk:organizationLocatedIn/sdk:locatedInState | sdk:locatedInState) ?state .

  OPTIONAL { ?state rdfs:label ?stateLabel . }
}
ORDER BY ?manufacturer ?state
LIMIT 10000

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?manufacturer ?label WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?label. }

  FILTER NOT EXISTS {
    ?manufacturer iof-core:describedBy ?desc .
    ?desc iof-scro:hasTextValue ?text .
    FILTER( str(?text) != "" && !regex(str(?text), "^\\s*$") )
  }
}
ORDER BY ?label
LIMIT 10000

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name WHERE {
  ?manuf a sdk:Manufacturer ;
          rdfs:label ?name ;
          sdk:hasCertificate ?cert .
  ?cert a sdk:ISO9001 .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsText WHERE {
  sdk:naics-332996.0-inst a sdk:NAICS332996.0 ;
    sdk:hasNAICSTextValue ?naicsText ;
    sdk:hasNAICSCodeValue ?code .
  FILTER(?code = "332996.0"^^xsd:integer)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naicsCode ?naicsText
WHERE {
  ?naicsInst a sdk:NAICS332996.0 ;
              sdk:hasNAICSTextValue ?naicsText ;
              sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(CONTAINS(?naicsText, "PIPE AND PIPE FITTING")) .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?capability ?name
WHERE {
  ?capability a sdk:MachiningCapability ;
              rdfs:label ?name .
  FILTER (str(?name) = "Machining")
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?empCount WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?name ;
           sdk:hasNumberOfEmployees ?empCount .
  FILTER(CONTAINS(LCASE(?name), "steel"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
 PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
 PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

 SELECT ?englishName WHERE {
   ?org a iof-core:Manufacturer ;
        rdfs:label ?englishName ;
        sdk:hasCertificate ?cert .
   ?cert a sdk:ISO9001 ;
         rdfs:label "ISO 9001" .
 }

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naicsText
WHERE {
  ?naics a sdk:NAICS332996.0 ;
         sdk:hasNAICSTextValue ?naicsText ;
         sdk:hasNAICSCodeValue ?code .
  FILTER(?code = 332996)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT DISTINCT ?code
WHERE {
  ?naicsInst a sdk:NAICS332996.0 ;
              sdk:hasNAICSTextValue ?text ;
              sdk:hasNAICSCodeValue ?code .
  FILTER(CONTAINS(LCASE(?text), "pipe and pipe fitting"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?lat WHERE {
  ?site a sdk:GeospatialLocation ;
        sdk:locatedInCity ?city ;
        sdk:hasSpatialCoordinates ?coords .
  ?coords a sdk:TwoDimensionalCartesianSpatialCoordinateDatum ;
          sdk:hasLatitudeValue ?lat .
  ?city rdfs:label ?cityLabel .
  FILTER(CONTAINS(LCASE(?cityLabel), "springfield"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?stateName WHERE {
  ?city a sdk:City ;
        rdfs:label ?cityLabel ;
        sdk:locatedInState ?state .
  FILTER(CONTAINS(LCASE(?cityLabel), "san ")).
  ?state a sdk:State ;
         rdfs:label ?stateName .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?codeValue ?codeText
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?name ;
                sdk:hasPrimaryNAICSClassifier ?naicsClassifier .
  FILTER(CONTAINS(LCASE(?name), "precision"))
  ?naicsClassifier sdk:hasNAICSCodeValue ?codeValue ;
                   sdk:hasNAICSTextValue ?codeText .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?industry ?industryLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              rdfs:label ?name ;
              sdk:suppliesToIndustry ?industry .
  FILTER(CONTAINS(LCASE(?name), "automation"))
  ?industry rdfs:label ?industryLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?product ?productLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
               rdfs:label ?name ;
               sdk:manufactures ?product .
  ?product a iof-core:MaterialProduct ;
           rdfs:label ?productLabel .
  FILTER(CONTAINS(LCASE(?name), "tooling"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?cap ?capLabel WHERE {
  ?org a iof-core:Manufacturer ;
       rdfs:label ?name .
  FILTER(CONTAINS(LCASE(?name), "aerospace"))
  ?org sdk:hasProcessCapability ?cap .
  ?cap rdfs:label ?capLabel .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manLabel ?cert ?certLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manLabel .
  FILTER(CONTAINS(LCASE(STR(?manLabel)), "plastics"))
  ?manufacturer sdk:hasCertificate ?cert .
  OPTIONAL { ?cert rdfs:label ?certLabel . }
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cityLabel WHERE {
  ?m a iof-core:Manufacturer ;
     rdfs:label ?name ;
     sdk:organizationLocatedIn ?site .
  FILTER (str(?name) = "Robotics") .
  ?site sdk:locatedInCity ?city .
  ?city a sdk:City ;
        rdfs:label ?cityLabel .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stateLabel WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?name ;
          sdk:organizationLocatedIn ?site .
  FILTER (str(?name) = "Valve")
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label ?stateLabel .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?lat ?lon WHERE {
  ?company a iof-core:Manufacturer ;
           rdfs:label ?compLabel .
  FILTER(?compLabel = "Surface Finish")
  ?company sdk:organizationLocatedIn ?site .
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat ;
          sdk:hasLongitudeValue ?lon .
}
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?certificate ?certificateLabel (COUNT(DISTINCT ?manufacturer) AS ?numManufacturers)
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
              sdk:hasCertificate ?certificate .
  ?certificate a ?certClass .
  FILTER(?certClass IN (sdk:ISO9001, sdk:ISO14001, sdk:ISO27001, sdk:ISO45001, sdk:ISO13485, sdk:ISOQualityCertificate, sdk:ISO50001, sdk:TL9000, sdk:QualityCertificate))
  OPTIONAL { ?certificate rdfs:label ?certificateLabel . }
}
GROUP BY ?certificate ?certificateLabel
ORDER BY ?certificateLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?naics (COUNT(?m) AS ?numManufacturers)
WHERE {
  ?m a iof-core:Manufacturer ;
     sdk:hasPrimaryNAICSClassifier ?naics .
}
GROUP BY ?naics
ORDER BY ?naics

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT ?manufacturer (COUNT(DISTINCT ?cap) AS ?totalCapabilities)
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  {
    ?manufacturer sdk:hasProcessCapability ?cap .
  } UNION {
    ?manufacturer sdk:hasMaterialCapability ?cap .
  }
}
GROUP BY ?manufacturer

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>

SELECT (COUNT(DISTINCT ?org) AS ?countWithoutDescription)
WHERE {
  ?org a iof-core:Manufacturer .
  FILTER NOT EXISTS {
    ?org iof-core:describedBy ?desc .
    ?desc a sdk:BusinessDescription .
  }
