               sdk:organizationLocatedIn ?site .
  OPTIONAL { ?manufacturer rdfs:label ?manufLabel . }
  ?site a sdk:GeospatialLocation ;
        sdk:hasSpatialCoordinates ?coords .
  OPTIONAL { ?coords sdk:hasLatitudeValue ?lat . }
  OPTIONAL { ?coords sdk:hasLongitudeValue ?lon . }
