PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?manufacturer ?manufacturerLabel ?hasISO9001
WHERE {
  ?manufacturer a iof-core:Manufacturer .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  BIND(EXISTS {
    ?manufacturer sdk:hasCertificate ?cert .
    ?cert a sdk:ISO9001 .
  } AS ?hasISO9001)
}
ORDER BY ?manufacturerLabel ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?category (COUNT(DISTINCT ?m) AS ?manufacturerCount)
WHERE {
  VALUES (?category ?class ?keyword) {
    ("Machining" sdk:MachiningCapability "machining")
    ("Coating" sdk:CoatingCapability "coating")
    ("Heat Treating" UNDEF "heat treating")
  }
  OPTIONAL {
    ?m a iof-core:Manufacturer ;
       sdk:hasProcessCapability ?cap .
    OPTIONAL {
      ?cap a ?capClass .
      ?capClass rdfs:subClassOf* ?class .
    }
    OPTIONAL {
      ?cap rdfs:label ?capLabel .
      FILTER(CONTAINS(LCASE(STR(?capLabel)), ?keyword))
      BIND(true AS ?labelHit)
    }
    FILTER(BOUND(?capClass) || BOUND(?labelHit))
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?stateLabel (AVG(?empNum) AS ?avgEmployees)
WHERE {
  {
    SELECT DISTINCT ?m ?state ?stateLabel ?empNum
    WHERE {
      ?m a iof-core:Manufacturer ;
         sdk:manufactures ?prod ;
         sdk:hasNumberOfEmployees ?emp ;
         sdk:organizationLocatedIn ?site .
      ?prod rdfs:label ?prodLabel .
      FILTER(CONTAINS(STR(?prodLabel), "Pipe"))
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      OPTIONAL { ?state rdfs:label ?stateLabel }
      BIND(xsd:integer(REPLACE(STR(?emp), ",", "")) AS ?empNum)
    }
  }
}
GROUP BY ?state ?stateLabel
ORDER BY ?stateLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?manufacturer ?label ?certCount
WHERE {
  {
    SELECT ?manufacturer (COUNT(?cert) AS ?certCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer .
      OPTIONAL { ?manufacturer sdk:hasCertificate ?cert . }
    }
    GROUP BY ?manufacturer
  }
  {
    SELECT (AVG(?cnt) AS ?avgCerts)
    WHERE {
      SELECT ?m (COUNT(?c) AS ?cnt)
      WHERE {
        ?m a iof-core:Manufacturer .
        OPTIONAL { ?m sdk:hasCertificate ?c . }
      }
      GROUP BY ?m
    }
  }
  FILTER(?certCount > ?avgCerts)
  OPTIONAL { ?manufacturer rdfs:label ?label . }
}
ORDER BY DESC(?certCount)

