PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?label
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?label ;
                sdk:hasNumberOfEmployees ?empLiteral ;
                sdk:hasProcessCapability ?cap ;
                sdk:organizationLocatedIn ?site .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state rdfs:label "Arizona" .

  ?cap a ?capType .
  ?capType rdfs:subClassOf* sdk:AdditiveManufacturingCapability .

  BIND(xsd:integer(REPLACE(STR(?empLiteral), ",", "")) AS ?emp)
  FILTER(?emp > 50)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasCertificate ?cert ;
                sdk:suppliesToIndustry ?aeroInd, ?autoInd .
  ?cert a sdk:ISO9001 .
  ?aeroInd rdfs:label ?aeroLabel .
  ?autoInd rdfs:label ?autoLabel .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  FILTER(CONTAINS(LCASE(STR(?aeroLabel)), "aerospace"))
  FILTER(CONTAINS(LCASE(STR(?autoLabel)), "automotive"))
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasProcessCapability ?cap ;
                sdk:hasNumberOfEmployees ?empRaw .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  ?industry a sdk:RenewableEnergyIndustry .
  ?cap a ?capClass .
  ?capClass rdfs:subClassOf* sdk:CoatingCapability .
  BIND(xsd:integer(REPLACE(STR(?empRaw), ",", "")) AS ?emp)
  FILTER(?emp > 200)
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?state ?stateLabel ?manufacturer ?manufacturerLabel ?productCount
WHERE {
  {
    SELECT ?state ?manufacturer (COUNT(DISTINCT ?product) AS ?productCount)
    WHERE {
      ?manufacturer a iof-core:Manufacturer ;
                    sdk:organizationLocatedIn ?site ;
                    sdk:manufactures ?product .
      ?site sdk:locatedInCity ?city .
      ?city sdk:locatedInState ?state .
      FILTER EXISTS { ?manufacturer sdk:hasCertificate ?cert . }
    }
    GROUP BY ?state ?manufacturer
  }
  {
    SELECT ?state (MAX(?pc) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?manufacturer (COUNT(DISTINCT ?product) AS ?pc)
        WHERE {
          ?manufacturer a iof-core:Manufacturer ;
                        sdk:organizationLocatedIn ?site2 ;
                        sdk:manufactures ?product .
          ?site2 sdk:locatedInCity ?city2 .
          ?city2 sdk:locatedInState ?state .
          FILTER EXISTS { ?manufacturer sdk:hasCertificate ?c . }
        }
        GROUP BY ?state ?manufacturer
      }
    }
    GROUP BY ?state
  }
  FILTER (?productCount = ?maxCount)
  OPTIONAL { ?state rdfs:label ?stateLabel . }
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
}
ORDER BY ?state ?manufacturer

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?matCap ;
                sdk:organizationLocatedIn ?site ;
                rdfs:label ?manufacturerLabel .
  ?matCap a sdk:CeramicProcessingCapability .
  ?site sdk:locatedInCity ?city .
  ?city sdk:locatedInState ?state .
  ?state a sdk:State ;
         rdfs:label ?stateLabel .
  FILTER(STRSTARTS(LCASE(STR(?stateLabel)), "new"))
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?industry ?industryLabel (COUNT(DISTINCT ?supplier) AS ?supplierCount)
WHERE {
  ?supplier a iof-core:Manufacturer ;
            sdk:suppliesToIndustry ?industry ;
            sdk:manufactures ?product .
  ?product rdfs:label ?prodLabel .
  FILTER(regex(str(?prodLabel), "pipe", "i"))
  OPTIONAL { ?industry rdfs:label ?industryLabel . }
}
GROUP BY ?industry ?industryLabel
HAVING (COUNT(DISTINCT ?supplier) > 100)
ORDER BY DESC(?supplierCount)

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?industry ;
                sdk:hasProcessCapability ?capM , ?capS .
  ?industry rdfs:label "Automotive" .
  ?capM a sdk:MachiningCapability .
  ?capS a sdk:SurfaceFinishingCapability .
}
ORDER BY ?manufacturerLabel

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?state ?stateLabel
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                sdk:hasMaterialCapability ?matCap ;
                sdk:organizationLocatedIn ?manuSite .
  ?matCap a sdk:GraphiteProcessingCapability .
  ?manuSite sdk:locatedInCity ?manuCity .
  ?manuCity sdk:locatedInState ?state .
  OPTIONAL { ?manufacturer rdfs:label ?manufacturerLabel . }
  OPTIONAL { ?state rdfs:label ?stateLabel . }

  ?supplier sdk:organizationLocatedIn ?supSite ;
            sdk:suppliesToIndustry ?industry .
  ?industry a sdk:RenewableEnergyIndustry .
  ?supSite sdk:locatedInCity ?supCity .
  ?supCity sdk:locatedInState ?state .
}

PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX iof-scro: <https://spec.industrialontologies.org/ontology/supplychain/SupplyChain/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX bfo: <http://purl.obolibrary.org/obo/>

SELECT ?city ?cityLabel (AVG(?emp) AS ?avgEmployeeCount)
WHERE {
  {
    SELECT DISTINCT ?city ?cityLabel ?org (xsd:integer(REPLACE(STR(?rawEmp), ",", "")) AS ?emp)
    WHERE {
      ?org a iof-core:Manufacturer ;
           sdk:hasProcessCapability ?cap ;
           sdk:organizationLocatedIn ?site ;
           sdk:hasNumberOfEmployees ?rawEmp .
      ?cap a ?capType .
      VALUES ?capType {
        sdk:HeatTreatingCapability
        sdk:StressRelievingCapability
        sdk:ThroughHardeningCapability
        sdk:AustemperingCapability
        sdk:TemperingCapability
        sdk:FullAnnealingCapability
        sdk:SurfaceHardeningCapability
        sdk:AnnealingCapability
        sdk:HardeningCapability
        sdk:ColdTreatmentCapability
      }
      ?site sdk:locatedInCity ?city .
      OPTIONAL { ?city rdfs:label ?cityLabel . }
    }
  }
}
GROUP BY ?city ?cityLabel
ORDER BY ?cityLabel

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?manufacturer ?manufacturerLabel ?lat
WHERE {
  ?manufacturer a iof-core:Manufacturer ;
                rdfs:label ?manufacturerLabel ;
                sdk:suppliesToIndustry ?indAgri ;
                sdk:suppliesToIndustry ?indConstr ;
                sdk:organizationLocatedIn ?site .
  ?indAgri rdfs:label ?agriLabel .
  ?indConstr rdfs:label ?constrLabel .
  FILTER(LCASE(STR(?agriLabel)) = "agriculture")
  FILTER(LCASE(STR(?constrLabel)) = "construction")
  ?site sdk:hasSpatialCoordinates ?coords .
  ?coords sdk:hasLatitudeValue ?lat .
  FILTER(xsd:float(?lat) > 40.0)
}

